export class InputError extends Error{constructor(code,detail=''){super(code);this.code=code;this.detail=detail;}}
export function day(s){if(!/^\d{4}-\d{2}-\d{2}$/.test(s)||Number(s.slice(0,4))<1900||Number(s.slice(0,4))>2100)throw new InputError('date');const d=new Date(s+'T00:00:00Z');if(!Number.isFinite(+d)||d.toISOString().slice(0,10)!==s)throw new InputError('date');return +d;}
function amount(s,max,zero=false){if(!/^\d+(\.\d{1,2})?$/.test(String(s))||Number(s)>max||Number(s)<(zero?0:0.01))throw new InputError('hours');return Number(s);}
export function parseCapacity(text,start,end){
 if(text.length>20000)throw new InputError('limit');const lines=text.split(/\r?\n/).filter(l=>l.trim());if(!lines.length)throw new InputError('capacity');if(lines.length>366)throw new InputError('limit');const days=[],seen=new Set();
 lines.forEach((line,i)=>{const fields=line.trim().split(/\s*,\s*|\s+/);if(fields.length!==2)throw new InputError('line',String(i+1));const [date,hours]=fields;let stamp;try{stamp=day(date);}catch{throw new InputError('line',String(i+1));}if(stamp<start||stamp>end)throw new InputError('range',String(i+1));if(seen.has(date))throw new InputError('duplicate',date);seen.add(date);let h;try{h=amount(hours,24,true);}catch{throw new InputError('line',String(i+1));}days.push({date,capacity:Math.floor(h*60+1e-8),left:Math.floor(h*60+1e-8),items:[]});});return days.sort((a,b)=>a.date.localeCompare(b.date));
}
export function plan({start,deadline,buffer,tasks,capacity}){
 const begin=day(start),end=day(deadline);if(end<begin||end-begin>365*86400000)throw new InputError('window');if(!/^\d+$/.test(String(buffer))||Number(buffer)>100)throw new InputError('buffer');if(!tasks.length||tasks.length>30)throw new InputError('tasks');
 const days=parseCapacity(capacity,begin,end),work=tasks.map((t,i)=>{if(typeof t.name!=='string'||!t.name.trim()||t.name.length>120)throw new InputError('name',String(i+1));let hours;try{hours=amount(t.hours,1000);}catch{throw new InputError('taskHours',String(i+1));}if(!/^[1-5]$/.test(String(t.priority)))throw new InputError('priority',String(i+1));const base=Math.ceil(hours*60-1e-8),need=Math.ceil(base*(100+Number(buffer))/100);return {...t,name:t.name.trim(),priority:Number(t.priority),index:i+1,base,need,allocated:0,missing:0};});
 const ordered=[...work].sort((a,b)=>a.priority-b.priority||a.index-b.index);
 for(const t of ordered){let remaining=t.need;for(let i=days.length-1;i>=0&&remaining>0;i--){const d=days[i],take=Math.min(d.left,remaining);if(take){d.left-=take;remaining-=take;t.allocated+=take;d.items.push({task:t.name,index:t.index,priority:t.priority,minutes:take});}}t.missing=remaining;}
 const totalCapacity=days.reduce((s,d)=>s+d.capacity,0),required=work.reduce((s,t)=>s+t.need,0),missing=work.reduce((s,t)=>s+t.missing,0);return {days,tasks:work,totalCapacity,required,missing,allocated:required-missing,bufferMinutes:work.reduce((s,t)=>s+t.need-t.base,0),feasible:missing===0};
}
export function csv(result,labels){const safe=s=>/^[\s]*[=+@-]/.test(s)?"'"+s:s;const rows=[labels.header];for(const d of result.days){if(!d.items.length)rows.push([d.date,'','',0,d.capacity,d.left,labels.idle]);for(const i of d.items)rows.push([d.date,safe(i.task),i.priority,i.minutes,d.capacity,d.left,labels.scheduled]);}for(const t of result.tasks)if(t.missing)rows.push(['',safe(t.name),t.priority,t.missing,'','',labels.missing]);return '\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');}
